{
  "item_id": "PRISMA_2020_3",
  "elements": [
    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Currently, there is no clarity regarding the prevalence of SARS-CoV-2 infection among HCWs according to specific clinical settings... Furthermore, it is unknown whether the clinical characteristics and outcomes of HCWs may be different from those of the general population",
      "reason": "The introduction describes existing knowledge (CDC case reports, transmission by asymptomatic carriers) and explicitly identifies uncertainties regarding prevalence, clinical characteristics, and outcomes in HCWs."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_1",
      "quote": "Therefore, characterizing SARS-CoV-2 infection within HCWs is critical for achieving optimal control of the pandemic. With the present systematic review and meta-analysis, we aimed to identify, analyze, and quantify the prevalence, risk factors, clinical characteristics, and outcomes of COVID-19 among HCWs.",
      "reason": "The importance of the review is explained (critical for pandemic control, designing preventive measures) and the review aim is stated."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "PRESENT",
      "chunk_id": "callout_0",
      "quote": "To our knowledge, this is the first systematic review quantifying the burden of COVID-19 among HCWs.",
      "reason": "The authors state this is the first systematic review on the topic, explaining the need for the current review; no previous review needed citation."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of prevalence, risk factors, and outcomes, not of intervention effects, so no mechanism of action is required."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not evaluate complex interventions or delivery contexts, so a logic model is not applicable."
    }
  ],
  "confidence": 92
}

